entries[37827] = { ["name"] = "Braufestkodo", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren Braufestkodo oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Ihr wisst nicht mehr genau, wie Ihr dieses Reittier erhalten habt. Allerdings erinnert Ihr Euch auch sonst kaum an die Ereignisse während des Braufests.\"\nKlassisch" }
entries[37828] = { ["name"] = "Großer Braufestkodo", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren großen Braufestkodo oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Coren Düsterbräu erhielt diesen Preis, nachdem er einen Taurendruiden unter den Tisch getrunken hatte - und dieser war noch in Bärengestalt. Es war einer der stolzesten Momente in Düsterbräus Leben.\"\nBeute von:\nFassförmige Schatzkiste\nFesttag:\nBraufest" }
